local w,h=Map.GetGridSize(); if w~=@WIDTH@ or h~=@HEIGHT@ then error('map grid mismatch '..w..'x'..h) end; local api=ExposedMembers.JAC_Resources; if not api then error('JAC_Resources API missing') end; local sites=@SITES@; local turn=Game.GetCurrentGameTurn(); local year=api.CurrentYear(); if year~=@YEAR@ then error('calendar year '..tostring(year)..', expected @YEAR@') end; local shown=Calendar.MakeYearStr(turn); if not string.find(shown,'@YEAR@',1,true) then error('engine date '..tostring(shown)..' is not @YEAR@') end; local function researched(tech) local info=tech~='' and GameInfo.Technologies[tech]; if not info then return false end; for _,p in ipairs(PlayerManager.GetAliveMajors()) do if p:GetTechs():HasTech(info.Index) then return true end end; return false end; local out=0; for _,s in ipairs(sites) do local t=Map.GetPlotByIndex(s[2]):GetResourceType(); if s[4]<=year then if t~=GameInfo.Resources[s[3]].Index then error('site not released: '..s[1]) end; out=out+1 elseif t~=-1 then if t~=GameInfo.Resources[s[3]].Index or not researched(s[5]) then error('site released too early: '..s[1]) end; out=out+1 end end; return 'year '..year..' (engine '..shown..', turn '..(turn-GameConfiguration.GetStartTurn())..'): '..out..' of '..#sites..' deferred sites on the map'